if (collides(state.ball, brick)) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  // Calculate overlaps to determine which face was hit
  const overlapL = state.ball.x + state.ball.r - brick.x;
  const overlapR = brick.x + brick.w - (state.ball.x - state.ball.r);
  const overlapT = state.ball.y + state.ball.r - brick.y;
  const overlapB = brick.y + brick.h - (state.ball.y - state.ball.r);

  const minOverlapX = Math.min(overlapL, overlapR);
  const minOverlapY = Math.min(overlapT, overlapB);

  if (minOverlapX < minOverlapY) {
    state.ball.vx *= -1;
    state.ball.x = overlapL < overlapR ? brick.x - state.ball.r : brick.x + brick.w + state.ball.r;
  } else {
    state.ball.vy *= -1;
    state.ball.y = overlapT < overlapB ? brick.y - state.ball.r : brick.y + brick.h + state.ball.r;
  }
}

