// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  frame,
} from './neon.js';


test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

test('frame: ball bounces off the top of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { 
    x: brick.x + brick.w / 2, 
    y: brick.y + 2, 
    r: 7, 
    vx: 0, 
    vy: 100 
  };

  const mockCtx = { 
    fillRect: () => {}, 
    beginPath: () => {}, 
    arc: () => {}, 
    fill: () => {}, 
    fillText: () => {},
    fillStyle: '',
    font: ''
  };

  frame(mockCtx, state);

  assert.ok(state.ball.vy < 0, 'Ball should bounce UP after hitting the top of a brick');
});

test('frame: ball bounces off the left side of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { 
    x: brick.x - 2, 
    y: brick.y + brick.h / 2, 
    r: 7, 
    vx: 100, 
    vy: 0 
  };

  const mockCtx = { 
    fillRect: () => {}, beginPath: () => {}, arc: () => {}, fill: () => {}, 
    fillText: () => {}, fillStyle: '', font: '' 
  };

  frame(mockCtx, state);

  assert.ok(state.ball.vx < 0, 'Ball should bounce LEFT after hitting the left side of a brick');
});

test('frame: ball bounces off the right side of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { 
    x: brick.x + brick.w + 2, 
    y: brick.y + brick.h / 2, 
    r: 7, 
    vx: -100, 
    vy: 0 
  };

  const mockCtx = { 
    fillRect: () => {}, beginPath: () => {}, arc: () => {}, fill: () => {}, 
    fillText: () => {}, fillStyle: '', font: '' 
  };

  frame(mockCtx, state);

  assert.ok(state.ball.vx > 0, 'Ball should bounce RIGHT after hitting the right side of a brick');
});

test('frame: ball bounces off the bottom of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { 
    x: brick.x + brick.w / 2, 
    y: brick.y + brick.h + 2, 
    r: 7, 
    vx: 0, 
    vy: -100 
  };

  const mockCtx = { 
    fillRect: () => {}, beginPath: () => {}, arc: () => {}, fill: () => {}, 
    fillText: () => {}, fillStyle: '', font: '' 
  };

  frame(mockCtx, state);


test('frame: ball tunnels through brick at high speed', () => {
  const state = createState(10); // High speed
  const brick = state.bricks[0];

  // Position ball just above the brick
  state.ball = { 
    x: brick.x + brick.w / 2, 
    y: brick.y - 2, // Top edge just above
    r: 7, 
    vx: 0, 
    vy: 1070 // ballSpeed(10)
  };

  const mockCtx = { 
    fillRect: () => {}, beginPath: () => {}, arc: () => {}, fill: () => {}, 
    fillText: () => {}, fillStyle: '', font: '' 
  };

  // Simulate one step and one frame
  step(state, 0.05); // Moves ball by 1070 * 0.05 = 53.5px
  frame(mockCtx, state);

  assert.equal(brick.alive, false, 'Brick should have been broken');
});

